"""Validate and export invoice JSON with total for the billing API (pydantic 1.10)."""
from datetime import datetime, timezone
from decimal import Decimal, ROUND_DOWN
from typing import List, Union

from pydantic import BaseModel, validator, ValidationError, root_validator

# Reuse Line and Invoice from json_export with slight extension for quantity >=1 and unit_price >=0
# We redefine here to add stricter validation as requested.

def _utc_z(dt: datetime) -> str:
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")


class Line(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @validator("quantity")
    def quantity_must_be_at_least_1(cls, v):
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @validator("unit_price", pre=True)
    def unit_price_must_be_decimal_and_nonnegative(cls, v):
        # Accept str/int/float, convert to Decimal
        try:
            dec = Decimal(v)
        except Exception:
            raise ValueError("unit_price must be a decimal number")
        if dec < 0:
            raise ValueError("unit_price must be >= 0")
        # Quantize to 2 decimal places without rounding up
        dec = dec.quantize(Decimal("0.01"), rounding=ROUND_DOWN)
        return dec


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v):
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError("issued_at must be a valid ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be a datetime or ISO 8601 string")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        # Remove microseconds for second precision
        dt = dt.replace(microsecond=0)
        return dt

    @root_validator
    def check_lines_not_empty(cls, values):
        lines = values.get("lines")
        if not lines:
            raise ValueError("lines must not be empty")
        return values


def export_invoice(data: dict) -> str:
    """
    Validate invoice data and return JSON text for billing API with total included.

    Input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive treated as UTC)
      - lines: list of dicts with sku (str), quantity (int >=1), unit_price (decimal >=0 as str/int/float)

    Output JSON keys:
      - number (str)
      - issued_at (str, formatted YYYY-MM-DDTHH:MM:SSZ UTC)
      - lines: list of dicts with sku, quantity, unit_price (string with exactly two decimals)
      - total: string with exactly two decimals (sum of quantity * unit_price)

    Raises ValueError on invalid input.
    """
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        raise ValueError(e)

    # Prepare output dict
    out = {
        "number": invoice.number,
        "issued_at": _utc_z(invoice.issued_at),
        "lines": [],
    }

    total = Decimal("0.00")
    for line in invoice.lines:
        # Format unit_price as string with exactly two decimals
        unit_price_str = f"{line.unit_price:.2f}"
        out["lines"].append({
            "sku": line.sku,
            "quantity": line.quantity,
            "unit_price": unit_price_str,
        })
        total += line.unit_price * line.quantity

    # Format total as string with two decimals
    total_str = f"{total.quantize(Decimal('0.01')):.2f}"
    out["total"] = total_str

    import json
    return json.dumps(out, separators=(",", ":"))

from typing import List, Optional

from pydantic import BaseModel, validator


class ImportProfile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @validator("display_name")
    def clean_display_name(cls, value):
        value = " ".join(value.split())
        if not value:
            raise ValueError("display_name must not be blank")
        return value

    @validator("zip_code", pre=True)
    def zip_code_to_str(cls, value):
        return str(value)


def import_profiles(rows: list) -> list:
    valid_profiles = []
    for row in rows:
        try:
            profile = ImportProfile.parse_obj(row)
        except Exception:
            continue
        valid_profiles.append(profile.dict())
    return valid_profiles

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import List, Union

from pydantic import BaseModel, Field, ValidationError, field_validator


class InvoiceLine(BaseModel):
    sku: str
    quantity: int = Field(..., ge=1)
    unit_price: Union[str, int, float, Decimal]

    model_config = {
        "from_attributes": True,
    }

    @field_validator("unit_price", mode="before")
    @classmethod
    def validate_unit_price(cls, v):
        try:
            d = Decimal(str(v))
        except Exception:
            raise ValueError("unit_price must be a decimal number")
        if d < 0:
            raise ValueError("unit_price must be >= 0")
        # Normalize to two decimals for internal use
        return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    @field_validator("sku")
    @classmethod
    def validate_sku(cls, v):
        if not isinstance(v, str) or not v:
            raise ValueError("sku must be a non-empty string")
        return v


class Invoice(BaseModel):
    number: str
    issued_at: Union[str, datetime]
    lines: List[InvoiceLine]

    model_config = {
        "from_attributes": True,
    }

    @field_validator("number")
    @classmethod
    def validate_number(cls, v):
        if not isinstance(v, str) or not v:
            raise ValueError("number must be a non-empty string")
        return v

    @field_validator("issued_at", mode="before")
    @classmethod
    def parse_issued_at(cls, v):
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError("issued_at must be ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be ISO 8601 datetime string or datetime")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt


def export_invoice(data: dict) -> str:
    """
    Validate an invoice dict and return JSON text for billing API.

    Input keys:
    - number: str
    - issued_at: ISO 8601 string or datetime (naive treated as UTC)
    - lines: list of dict with keys sku (str), quantity (int >= 1), unit_price (decimal >= 0 as str/int/float)

    Output JSON keys:
    - number: str
    - issued_at: str formatted "YYYY-MM-DDTHH:MM:SSZ" in UTC
    - lines: list of dict with sku (str), quantity (int), unit_price (str with two decimals)
    - total: str with two decimals (sum of quantity * unit_price)
    """
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError as e:
        # Raise ValueError as requested
        raise ValueError(str(e)) from e

    # Format issued_at as "YYYY-MM-DDTHH:MM:SSZ"
    issued_at_str = invoice.issued_at.strftime("%Y-%m-%dT%H:%M:%SZ")

    # Prepare lines with formatted unit_price and calculate total
    total = Decimal("0.00")
    lines_out = []
    for line in invoice.lines:
        line_total = line.unit_price * line.quantity
        total += line_total
        lines_out.append(
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit_price": f"{line.unit_price:.2f}",
            }
        )
    total_str = f"{total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}"

    # Compose output dict
    out = {
        "number": invoice.number,
        "issued_at": issued_at_str,
        "lines": lines_out,
        "total": total_str,
    }

    # Return JSON text
    import json

    return json.dumps(out, separators=(",", ":"))

from profile_models import load_profile


def import_profiles(rows: list) -> list:
    """Validate profile rows and return valid ones as dicts with required fields only, skipping invalid rows."""
    valid_profiles = []
    for row in rows:
        try:
            profile = load_profile(row)
        except ValueError:
            # Skip invalid rows silently
            continue
        # Include only the required fields with bio included (which may be None)
        # user_id as int, display_name as cleaned str, bio as str or None, zip_code as str
        profile_dict = {
            "user_id": profile.user_id,
            "display_name": profile.display_name,
            "bio": profile.bio,
            "zip_code": profile.zip_code,
        }
        valid_profiles.append(profile_dict)
    return valid_profiles

import re
from pydantic import BaseModel, field_validator, ValidationError


class SignupModel(BaseModel):
    username: str
    email: str
    phone: str
    password: str
    password_confirm: str

    @field_validator("username")
    @classmethod
    def validate_username(cls, v: str) -> str:
        if not re.fullmatch(r"^[a-z0-9_]{3,20}$", v):
            raise ValueError("username must match ^[a-z0-9_]{3,20}$")
        return v

    @field_validator("email")
    @classmethod
    def validate_email(cls, v: str) -> str:
        v = v.strip().lower()
        if "@" not in v:
            raise ValueError("email must contain '@'")
        return v

    @field_validator("phone")
    @classmethod
    def validate_phone(cls, v: str) -> str:
        # Remove spaces, dots, dashes, parentheses
        compact = re.sub(r"[ .\-\(\)]", "", v)
        if not re.fullmatch(r"\+[0-9]{8,15}", compact):
            raise ValueError("phone must be '+' followed by 8-15 digits after removing spaces, dots, dashes, parentheses")
        return compact

    @field_validator("password")
    @classmethod
    def validate_password(cls, v: str) -> str:
        if len(v) < 8:
            raise ValueError("password must be at least 8 characters")
        return v

    @field_validator("password_confirm")
    @classmethod
    def validate_password_confirm(cls, v: str, info) -> str:
        # We need to compare with password field
        password = info.data.get("password")
        if password is not None and v != password:
            raise ValueError("password_confirm must equal password")
        return v


def validate_signup(data: dict) -> dict:
    """Validate a sign-up payload and return dict with username, email, phone."""
    model = SignupModel.model_validate(data)
    return {
        "username": model.username,
        "email": model.email,
        "phone": model.phone,
    }
